import {
	useCallback,
	useEffect,
	useLayoutEffect,
	useRef,
	useState,
} from 'react';

import AnnouncementForm from './components/AnnouncementForm';
import AnnouncementList from './components/AnnouncementList';
import FlyerPreview from './components/FlyerPreview';
import SettingsPanel from './components/SettingsPanel';

const GOTHAM =
	"'Gotham', 'Montserrat', 'Century Gothic', 'Gill Sans', sans-serif";

const { ChevronDown, Check, Upload, X, ChevronUp, AlertTriangle, Trash2 } =
	LucideIcons;

const JK_OPTIONS = [
	'All Southeast Jamatkhanas',
	'All Metro Atlanta Jamatkhanas',
	'Atlanta Headquarters',
	'Atlanta Northeast',
	'Atlanta Northwest',
	'Atlanta South',
	'Duluth',
	'Birmingham',
	'Chattanooga',
	'Knoxville',
	'Memphis',
	'Nashville',
	'Spartanburg',
	'Raleigh (G)',
	'Charleston (G)',
	'Kentucky (G)',
];

const COLOR_OPTIONS = [
	{ label: 'Evergreen', value: '#005D35' },
	{ label: 'Gold', value: '#B4995A' },
	{ label: 'Charcoal', value: '#404040' },
	{ label: 'Custom…', value: '__custom__' },
];

const PRESET_COLORS = COLOR_OPTIONS.filter((c) => c.value !== '__custom__');

const FLYER_HDR = '#005D35';
const FLYER_GOLD = '#B4995A';
const FLYER_BG = '#F5F4EE';

// ── Auto-color cycle: Evergreen → Gold → Charcoal → … ─────────────────────────
const getNextIconBg = (count) =>
	PRESET_COLORS[count % PRESET_COLORS.length].value;

// Is the given hex value one of the presets?
const isPreset = (hex) => PRESET_COLORS.some((c) => c.value === hex);

const DEFAULT_FORM = {
	iconUrl: null,
	iconBg: PRESET_COLORS[0].value,
	title: '',
	description: '',
	date: '',
	time: '',
	timezone: 'EST',
	venue: '',
	jamatkhanas: [],
};

const blankForm = (announcementCount) => ({
	...DEFAULT_FORM,
	iconBg: getNextIconBg(announcementCount),
});

const SAMPLE = [
    {
        "iconUrl": "data:image/png;base64,",
        "iconBg": "#B52B40",
        "title": "AKEB | Decoding The SAT/ACT",
        "description": "Are you a rising 10-12th grader looking for extra SAT/ACT prep support? Register now for this summer’s prep sessions and mock exam at tinyurl.com/DecodingSATACT. The deadline to register is Saturday, May 23.",
        "date": "",
        "time": "",
        "timezone": "EST",
        "venue": "",
        "jamatkhanas": [],
        "id": 1778814679081
    },
    {
        "iconUrl": "data:image/png;base64,",
        "iconBg": "#B52B40",
        "title": "AKEB | School & Neighborhood Quality Session",
        "description": "Parents of children from all age groups are invited to join an AKEB information session to learn more about school and neighborhood quality on Sunday, May 23, after evening ceremonies at Atlanta Headquarters Jamatkhana Social Hall.",
        "date": "2026-05-23",
        "time": "",
        "timezone": "EST",
        "venue": "Atlanta Headquarters Jamatkhana",
        "jamatkhanas": [],
        "id": 1778814958030
    },
    {
        "iconUrl": "data:image/png;base64,",
        "iconBg": "#005D35",
        "title": "Pause At The Peak",
        "description": "⁠Pause at the Peak and enjoy a hike up Stone Mountain on Sunday, May 24, at 8AM. Registration is required.",
        "date": "2026-05-24",
        "time": "08:00",
        "timezone": "EST",
        "venue": "Stone Mountain, 1000 Robert E. Lee Blvd, Stone Mountain, GA, 30083",
        "jamatkhanas": [],
        "id": 1778815294682
    },
    {
        "iconUrl": "data:image/png;base64,",
        "iconBg": "#D2691E",
        "title": "Aging Gracefully Initiative | Chai Time",
        "description": "<strong>Northeast and Duluth AGI Members Only</strong>:Chai Time will be held every Monday from 4-6pm at Northeast Jamatkhana social hall. For details, contact AGI volunteers.",
        "date": "",
        "time": "",
        "timezone": "EST",
        "venue": "",
        "jamatkhanas": [],
        "id": 1779429381506
    },
    {
        "iconUrl": "data:image/png;base64,",
        "iconBg": "#D2691E",
        "title": "Aging Gracefully Initiative | Movie",
        "description": "AGI Golden Club members are invited to watch a movie on Sunday, May 31, at 6:00pm in Northeast Jamatkhana social hall. For more details, contact AGI volunteers.  ",
        "date": "2026-05-31",
        "time": "18:00",
        "timezone": "EST",
        "venue": "Northeast Jamatkhana Social Hall",
        "jamatkhanas": [],
        "id": 1779429336363
    }
]

// ── Helpers ────────────────────────────────────────────────────────────────────

// ── Main App ───────────────────────────────────────────────────────────────────
export default function FlyerApp() {
	const [announcements, setAnnouncements] = useState(SAMPLE);
	const [form, setForm] = useState(() => blankForm(SAMPLE.length));
	const [editingId, setEditingId] = useState(null);
	const [activeTab, setActiveTab] = useState('add');
	const [headerTitle, setHeaderTitle] = useState('LOCAL ANNOUNCEMENTS');
	const [headerSubtitle, setHeaderSubtitle] = useState('Friday, May 22, 2026');
	const [footerUrl, setFooterUrl] = useState('https://tinyurl.com/SEWeekly');
	const [exporting, setExporting] = useState(null);
	const [overflowError, setOverflowError] = useState(false);
	const [pendingId, setPendingId] = useState(null);
	const [pendingForm, setPendingForm] = useState(null);

	console.log(announcements);

	const previewRef = useRef(null);
	const bodyRef = useRef(null);

	// ── Overflow check ─────────────────────────────────────────────────────────
	useLayoutEffect(() => {
		if (pendingId === null || !bodyRef.current) return;
		const el = bodyRef.current;
		if (el.scrollHeight > el.clientHeight) {
			setAnnouncements((prev) => prev.filter((a) => a.id !== pendingId));
			if (pendingForm) setForm(pendingForm);
			setOverflowError(true);
			setActiveTab('add');
		} else {
			setOverflowError(false);
			setForm(blankForm(announcements.length));
			setActiveTab('list');
		}
		setPendingId(null);
		setPendingForm(null);
	}, [pendingId, announcements]);

	useEffect(() => {
		if (overflowError && bodyRef.current) {
			const el = bodyRef.current;
			if (el.scrollHeight <= el.clientHeight) setOverflowError(false);
		}
	}, [announcements, overflowError]);

	useEffect(() => {
		const load = (src, cb) => {
			if (document.querySelector(`script[src="${src}"]`)) {
				cb && cb();
				return;
			}
			const s = document.createElement('script');
			s.src = src;
			s.onload = cb;
			document.head.appendChild(s);
		};
		load(
			'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js',
			() =>
				load(
					'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js',
				),
		);
	}, []);

	// ── Handlers ───────────────────────────────────────────────────────────────

	const handleSubmit = useCallback(() => {
		if (!form.title.trim()) return;
		if (editingId !== null) {
			setAnnouncements((prev) =>
				prev.map((a) => (a.id === editingId ? { ...form, id: editingId } : a)),
			);
			setEditingId(null);
			setForm(blankForm(announcements.length));
			setActiveTab('list');
		} else {
			const newId = Date.now();
			setPendingForm({ ...form });
			setAnnouncements((prev) => [...prev, { ...form, id: newId }]);
			setPendingId(newId);
		}
	}, [form, editingId, announcements.length]);

	const handleEdit = useCallback((ann) => {
		setForm({ ...DEFAULT_FORM, ...ann });
		setEditingId(ann.id);
		setActiveTab('add');
	}, []);

	const handleDelete = useCallback(
		(id) => {
			setAnnouncements((prev) => prev.filter((a) => a.id !== id));
			if (editingId === id) {
				setEditingId(null);
				setForm(blankForm(announcements.length - 1));
			}
		},
		[editingId, announcements.length],
	);

	const handleCancel = useCallback(() => {
		setEditingId(null);
		setForm(blankForm(announcements.length));
		setOverflowError(false);
	}, [announcements.length]);

	const handleClearAll = useCallback(() => {
		setAnnouncements([]);
		setEditingId(null);
		setOverflowError(false);
		setForm(blankForm(0));
	}, []);

	const handleMoveUp = useCallback((idx) => {
		if (idx === 0) return;
		setAnnouncements((prev) => {
			const next = [...prev];
			[next[idx - 1], next[idx]] = [next[idx], next[idx - 1]];
			return next;
		});
	}, []);

	const handleMoveDown = useCallback((idx) => {
		setAnnouncements((prev) => {
			if (idx >= prev.length - 1) return prev;
			const next = [...prev];
			[next[idx], next[idx + 1]] = [next[idx + 1], next[idx]];
			return next;
		});
	}, []);

	const handleExport = async (fmt) => {
		if (!window.html2canvas || !previewRef.current) {
			alert(
				'Export libraries still loading. Please wait a moment and try again.',
			);
			return;
		}
		setExporting(fmt);
		try {
			const canvas = await window.html2canvas(previewRef.current, {
				scale: 2,
				useCORS: true,
				allowTaint: true,
				backgroundColor: FLYER_BG,
				logging: false,
			});
			if (fmt === 'pdf') {
				const { jsPDF } = window.jspdf;
				const w = canvas.width / 2,
					h = canvas.height / 2;
				const pdf = new jsPDF({
					orientation: w > h ? 'landscape' : 'portrait',
					unit: 'px',
					format: [w, h],
				});
				pdf.addImage(canvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, w, h);
				pdf.save('announcement-flyer.pdf');
			} else {
				const a = document.createElement('a');
				a.download = `announcement-flyer.${fmt}`;
				a.href = canvas.toDataURL(`image/${fmt}`, 0.95);
				a.click();
			}
		} catch (e) {
			alert('Export failed: ' + e.message);
		}
		setExporting(null);
	};

	const TABS = [
		{
			id: 'add',
			label:
				overflowError && !editingId ? '⚠ Add' : editingId ? '✏ Edit' : '+ Add',
		},
		{ id: 'list', label: `≡ List (${announcements.length})` },
		{ id: 'settings', label: '⚙ Settings' },
	];

	return (
		<div
			style={{
				display: 'flex',
				height: '100vh',
				background: '#1a1a1a',
				fontFamily: GOTHAM,
				overflow: 'hidden',
			}}>
			{/* ── Left Panel ── */}
			<div
				style={{
					width: 360,
					background: '#faf9f5',
					display: 'flex',
					flexDirection: 'column',
					boxShadow: '2px 0 12px rgba(0,0,0,0.2)',
					zIndex: 10,
					flexShrink: 0,
				}}>
				<div
					style={{
						background: FLYER_HDR,
						padding: '14px 16px 12px',
					}}>
					<div
						style={{
							color: 'white',
							fontWeight: 800,
							fontSize: 15,
							letterSpacing: 0.5,
						}}>
						Flyer Builder
					</div>
					<div
						style={{
							color: 'rgba(255,255,255,0.55)',
							fontSize: 10.5,
							marginTop: 2,
							letterSpacing: 1.5,
							textTransform: 'uppercase',
						}}>
						Ismaili Council — Southeast USA
					</div>
				</div>

				{/* Tabs */}
				<div
					style={{
						display: 'flex',
						background: 'white',
						borderBottom: '1px solid #e5e2d8',
					}}>
					{TABS.map((tab) => {
						const isError = tab.id === 'add' && overflowError && !editingId;
						return (
							<button
								key={tab.id}
								onClick={() => setActiveTab(tab.id)}
								style={{
									flex: 1,
									padding: '9px 0',
									border: 'none',
									cursor: 'pointer',
									background:
										activeTab === tab.id
											? isError
												? '#fef2f2'
												: '#f0f7f4'
											: 'white',
									color: isError
										? '#c0392b'
										: activeTab === tab.id
											? FLYER_HDR
											: '#777',
									fontWeight: activeTab === tab.id ? 700 : 400,
									fontSize: 11.5,
									borderBottom:
										activeTab === tab.id
											? `2px solid ${isError ? '#c0392b' : FLYER_HDR}`
											: '2px solid transparent',
								}}>
								{tab.label}
							</button>
						);
					})}
				</div>

				<div style={{ flex: 1, overflowY: 'auto', padding: 16 }}>
					{activeTab === 'add' && (
						<AnnouncementForm
							form={form}
							setForm={setForm}
							onSubmit={handleSubmit}
							isEditing={editingId !== null}
							onCancel={handleCancel}
							overflowError={overflowError && !editingId}
						/>
					)}
					{activeTab === 'list' && (
						<AnnouncementList
							announcements={announcements}
							onEdit={handleEdit}
							onDelete={handleDelete}
							onMoveUp={handleMoveUp}
							onMoveDown={handleMoveDown}
							onClearAll={handleClearAll}
						/>
					)}
					{activeTab === 'settings' && (
						<SettingsPanel
							headerTitle={headerTitle}
							setHeaderTitle={setHeaderTitle}
							headerSubtitle={headerSubtitle}
							setHeaderSubtitle={setHeaderSubtitle}
							footerUrl={footerUrl}
							setFooterUrl={setFooterUrl}
						/>
					)}
				</div>

				{/* Export Row */}
				<div
					style={{
						padding: '12px 14px',
						borderTop: '1px solid #e5e2d8',
						background: 'white',
					}}>
					<div
						style={{
							fontSize: 10,
							color: '#aaa',
							marginBottom: 7,
							letterSpacing: 1,
							textTransform: 'uppercase',
							fontWeight: 600,
						}}>
						Export Flyer
					</div>
					<div style={{ display: 'flex', gap: 7 }}>
						{['PNG', 'JPEG', 'PDF'].map((fmt) => (
							<button
								key={fmt}
								onClick={() => handleExport(fmt.toLowerCase())}
								disabled={!!exporting}
								style={{
									flex: 1,
									padding: '9px 0',
									border: 'none',
									borderRadius: 6,
									cursor: exporting ? 'default' : 'pointer',
									background:
										exporting === fmt.toLowerCase() ? '#7aab95' : FLYER_HDR,
									color: 'white',
									fontWeight: 700,
									fontSize: 12,
									letterSpacing: 0.5,
									transition: 'background 0.2s',
								}}>
								{exporting === fmt.toLowerCase() ? '…' : `↓ ${fmt}`}
							</button>
						))}
					</div>
				</div>
			</div>

			{/* ── Right Panel (Preview) ── */}
			<div
				style={{
					flex: 1,
					overflowY: 'auto',
					padding: '32px 40px',
					display: 'flex',
					flexDirection: 'column',
					alignItems: 'center',
				}}>
				<div
					style={{
						marginBottom: 12,
						color: 'rgba(255,255,255,0.4)',
						fontSize: 10,
						letterSpacing: 2,
						textTransform: 'uppercase',
					}}>
					Live Preview — US Letter (8.5" × 11")
				</div>
				<div
					ref={previewRef}
					style={{
						boxShadow: '0 8px 40px rgba(0,0,0,0.5)',
						borderRadius: 2,
						flexShrink: 0,
					}}>
					<FlyerPreview
						announcements={announcements}
						headerTitle={headerTitle}
						headerSubtitle={headerSubtitle}
						footerUrl={footerUrl}
						bodyRef={bodyRef}
					/>
				</div>
				<div style={{ height: 40 }} />
			</div>
		</div>
	);
}
